// Sprint 5 independent validation (s5-validation): set payloads built by the REAL frontend chain
// render() frames -> createCurlSet (curl analyzer + issue tracker) -> finish() -> buildSetSummary
// -> buildWorkoutSetPayload. Frames are SYNTHETIC (tests/fixtures/coaching-fixtures.js); they prove the
// wire contract and field round trip only, not counting or detection accuracy on a person.
//
// `node tests/fixtures/workout-payload-fixtures.js --write` regenerates
// backend/tests/fixtures/frontend_set_payloads.json (used by backend/tests/test_idempotency.py).
import { writeFileSync } from 'node:fs';
import process from 'node:process';
import { fileURLToPath } from 'node:url';
import { createCurlSet } from '../../src/exercises/setSession.js';
import { createCurlAnalyzer } from '../../src/exercises/curl.js';
import { createCurlIssueTracker } from '../../src/exercises/curlRules.js';
import { buildWorkoutSetPayload } from '../../src/api/workoutPayload.js';
import { curlsWithIssues } from './coaching-fixtures.js';

export const SYNTHETIC = true;
/** Fixed wall clock for reproducible payloads (in the past, after 2020, as the server requires). */
export const FIXED_ENDED_AT = '2026-10-01T12:00:00.000Z';

const CUE_LOG = [{ atMs: 1500, cueId: 'positioning', text: 'Stand side-on.', spoken: false }];

/**
 * Run SYNTHETIC curls through the real set lifecycle and build the payload the camera page would send.
 * @param {Object} [options]
 * @param {'validated-only'|'review'} [options.mode] 'validated-only' is today's app (no rule enabled).
 * @param {boolean} [options.noFrames] Finish before any frame (side/view/featureVersion null).
 */
export function realSetPayload({ mode = 'validated-only', noFrames = false, seed = 11, endedAt = FIXED_ENDED_AT } = {}) {
  const analyzer = createCurlAnalyzer();
  const tracker = createCurlIssueTracker();
  const set = createCurlSet({ analyzer, tracker });
  let finishMs = 1000;
  if (!noFrames) {
    const frames = curlsWithIssues({ seed, reps: [{ torso: 20, durationMs: 3000 }, {}, { drift: 25, durationMs: 3000 }, {}, { excursion: 60 }] });
    for (const frame of frames) set.update(frame);
    finishMs = frames.at(-1).timestampMs;
  }
  const completed = set.finish(finishMs, { cueLog: CUE_LOG, mode, enabledRuleTypes: [], feedbackVersion: 'feedback-1.1.0' });
  const payload = buildWorkoutSetPayload({ summary: completed.summary, completedReps: analyzer.getSession().completedReps, endedAt });
  return { summary: completed.summary, completedReps: analyzer.getSession().completedReps, payload };
}

export function backendFixture() {
  return {
    _comment: 'SYNTHETIC frames through the real frontend chain (createCurlSet -> buildSetSummary -> buildWorkoutSetPayload). '
      + 'Generated by frontend/tests/fixtures/workout-payload-fixtures.js --write. Proves the wire contract only.',
    validatedOnly: realSetPayload({ mode: 'validated-only' }).payload,
    review: realSetPayload({ mode: 'review' }).payload,
    noFrames: realSetPayload({ noFrames: true }).payload,
  };
}

if (process.argv[1] === fileURLToPath(import.meta.url) && process.argv.includes('--write')) {
  const target = fileURLToPath(new URL('../../../backend/tests/fixtures/frontend_set_payloads.json', import.meta.url));
  writeFileSync(target, `${JSON.stringify(backendFixture(), null, 1)}\n`);
  console.log(`wrote ${target}`);
}
